    "explanation": "【公式解説】\n正解は「1円の狂いも許されない定型計算・転記（①）は表計算や既存システムに任せ、非構造化テキストの要約・文案作成（②）にClaudeを活用し、特例契約の最終判断（③）は人間が行う設計にする。」です。\n\n■ ソリューション設計の黄金律（Right Tool for the Job）:\n業務フロー統合で最も重要なのは**「何でもかんでもLLMにやらせない」**ことです。\n1. **決定論的ルール・厳密計算**: 既存のプログラム・RPA・Excel関数が最速・最安・100%正確。\n2. **非構造化データの理解・要約・ドラフト生成・分類**: Claudeが最も高い付加価値を出す領域。\n3. **高リスクな例外判断・説明責任**: 人間（Human-in-the-Loop）が最終決定。",
