    "explanation": "【公式解説】\n正解は「①まず各コメントに「機能領域タグ」と「深刻度」を付与して一覧化し、②上位課題テーマごとに代表的な生コメントを抜粋させ、③人間が優先順位を決定した上で改善企画書のドラフトを作成させる。」です。\n\n■ 非構造化データの業務統合パイプライン（Classify → Aggregate → Review → Draft）:\n大量の定性データ（VOC・アンケート・日報）を扱う業務では、いきなり最終結論を出させるのではなく、\n1. **構造化・タグ付け（Classification）**\n2. **傾向の集約と代表例の抽出（Synthesis with Evidence）**\n3. **人間の意思決定（Prioritization）**\n4. **アクションプランの下書き（Drafting）**\nというステップに分けることで、根拠の透明性と圧倒的な時短を両立できます。",
