    "question": "【CCDV-F 実戦シナリオ 第13問】\nドキュメント分析バッチが特定の顧客データセットを処理した際、Anthropic APIから `HTTP 413 (request_too_large)` エラーが返却されました。開発者が自動リトライ機構で3回再送しましたが、すべて同じ413エラーで即座に失敗しています。このエラーの根本原因と正しい解決策はどれですか。",
