    "type": "multiple",
    "question": "【CCDV-F 実戦シナリオ 第19問｜2つ選択】\nエンジニアがMessages APIのSSEストリーミング（`stream: true`）を用いて、リアルタイム対話およびツール呼び出しを行うチャットアプリケーションを開発しています。ストリームイベントの処理とマルチターン履歴の構築に関して、正しく実装すべき要件を **2つ** 選択してください。（Select TWO）",
