    "explanation": "【公式アーキテクチャ解説】\n正解は「出力直前のテキストを正規表現やPII検出器で検査し、該当箇所を自動マスキングするPostToolUse/Output Hookの導入」です。\n\nPII（個人識別情報）や機密データの漏洩防止において、LLMの生成段階でのプロンプト抑制だけに頼るのは極めて危険です。\nアーキテクチャとして「Output Hook（またはPostToolUse Hook / Data Loss Prevention Gateway）」を組み込み、Claudeが生成したテキストがクライアントに届く直前のレイヤーで、Presidioや専用の正規表現エンジンを用いてクレジットカード番号、マイナンバー、電話番号等を検知し、`[REDACTED]` や `****-****-****-1234` に機械的に置換（マスキング）して配信するのがエンタープライズの標準です。\n\n⚠️ 引っかけポイント: プロンプトへの注意書きは漏洩リスクをゼロにできず、Base64化は難読化に過ぎず根本解決になりません。",
