    "explanation": "【公式アーキテクチャ解説】\n正解は「最小権限の非rootユーザーと揮発性ストレージを用い、ネットワークを制限した使い捨てDockerコンテナ内で実行する設計」です。\n\n`--dangerously-skip-permissions`（パーミッションスキップ）は、人間による承認をバイパスするため、文字通り極めて高リスクなモードです。\nAnthropicのセキュリティベストプラクティスでは、このフラグを使用する際は「厳格なサンドボックス環境（Containerized Sandbox）」が絶対条件となります。\n具体的には：\n1. ホスト環境から完全に隔離された使い捨てコンテナ（Ephemeral Container）\n2. 非rootユーザー（UID 1000等）による実行\n3. 外部インターネットへの通信制限（内部プロキシ経由またはDNSホワイトリスト）\n4. ホストの重要ボリューム（`/`, `~/.ssh`, クラウド認証情報等）を絶対にマウントしないこと\nこれらを組み合わせることで、万一の暴走時にも被害をコンテナ内部の揮発性領域に封じ込めます。\n\n⚠️ 引っかけポイント: プロンプト（CLAUDE.md）での禁止指示は脱獄や誤動作で容易に突破されるため、セキュリティ境界（OS/コンテナレベルの物理隔離）にはなり得ません。",
    "officialRef": "Anthropic Certified Architect Guide: Claude Code Sandboxing & Permission Management"
