    "explanation": "【公式アーキテクチャ解説】\n正解は「Server-Sent Events（SSE）を用いたストリーミングAPIを採用し、トークン単位のデルタ差分を受信・即時レンダリングする設計」です。\n\n開発者向けツール（IDE拡張機能やCLI）におけるUXの最重要指標が「Time to First Token（TTFT: 最初のトークンが表示されるまでの時間）」です。\nClaudeのMessages APIで `stream: true` を指定すると、サーバーからServer-Sent Events（SSE）形式で `content_block_delta` イベントがミリ秒単位で逐次配信されます。クライアントはこれを受信した瞬間にエディタの差分ビュー（Inline Diff）へリアルタイムにタイピングアニメーションのように描画することで、開発者は数秒待つだけで生成内容を確認でき、途中で意図と異なる場合は即座に停止（Abort）することも可能になります。\n\n⚠️ 引っかけポイント: ポーリングは非効率であり、瞑想の強制や行数の極端な制限はツールとしての価値を損ないます。",
