    "question": "【シナリオ：Claude Code の CI/CD 組み込み】\n前提: GitHub Actions ワークフローにおいて、プルリクエスト（PR）が作成された際に Claude Code CLI を起動し、コードレビューと静的解析の要約を自動生成するCIジョブを構築している。\n\n状況・課題:\nCI環境はキーボード入力を行う人間が存在しない「非対話環境（Non-interactive / Headless）」である。\n通常の対話モードで Claude Code を起動すると、ユーザーからのプロンプト入力を待ってジョブが永久にフリーズ（ハング）してしまい、CIのタイムアウト（数時間後）まで終了しない障害が発生した。\n\n問い:\nGitHub Actions などのCI/CDパイプラインにおいて、Claude Code を完全自動のヘッドレス（非対話）で実行し、結果を標準出力に取得するための正しいCLIオプションはどれか？",
