    "question": "【シナリオ：Claude Code の CI/CD 組み込み】\n前提: チームでは変更履歴の追跡や自動リリースノート生成（Semantic Release）のため、「Conventional Commits（例: `feat: ...`, `fix: ...`, `chore: ...`）」に準拠したコミットメッセージが義務付けられている。\n\n状況・課題:\nClaude Code が自動でコード修正をコミットする際、「バグ直した」「Update code」「fix」といった曖昧で非標準なコミットメッセージを作成してしまい、リリースタグの自動生成ツールがパースエラーを起こして停止してしまった。\n\n問い:\nClaude Code によるコミットメッセージの生成において、Conventional Commits 規約を確実に遵守させるための設定・アーキテクチャ設計はどれか？",
