    "explanation": "【公式アーキテクチャ解説】\n正解は「非rootユーザー（USER 1000）でコンテナを実行し、ホストのDockerソケットマウントを禁止し特権（--privileged）を無効化する設計」です。\n\nCIランナーおよびコンテナセキュリティにおけるベストプラクティスです。\nエージェントが任意のシェルコマンドを実行できる環境をコンテナ化する場合：\n1. **非root実行**: Dockerfileで `USER node` や `USER nonroot:nonroot`（UID 1000等）を指定し、コンテナ内でのroot権限を剥奪する。\n2. **Dockerソケットマウントの厳禁**: `/var/run/docker.sock` をマウントすると、コンテナ内からホストのDockerデーモンを操作して簡単にコンテナエスケープが可能になるため、絶対にマウントしてはならない。\n3. **Privilegedフラグの排除**: `--privileged` フラグはカーネルケーパビリティを全開放するため厳禁とし、必要最小限のCapabilitiesのみを付与する。\n\n⚠️ 引っかけポイント: `--privileged` の付与や `chmod 777` はセキュリティ防御を完全に自爆させる極めて危険なアンチパターンです。",
