    "question": "【シナリオ：Claude Code の CI/CD 組み込み】\n前提: CI/CDパイプラインに導入された Claude Code によるコードレビュー機能が、全社で本格稼働している。\n\n状況・課題:\nエンジニアリングマネージャーが「AIレビューの導入によって、実際にPRマージまでの時間が短縮されたのか」「開発者がAIの指摘をどれくらい受け入れているのか」を定量的に測定し、経営陣に投資対効果（ROI）を報告する必要がある。\n\n問い:\nAIコードレビューの運用効果と開発者満足度を継続的に評価・監視するための代表的なメトリクス（KPI）の組み合わせはどれか？",
