    "question": "【シナリオ：構造化データ抽出】\n前提: 医療機関の電子カルテや保険請求明細（レセプト）から、病名、治療コード、投薬履歴の構造化データを抽出し、医療研究用データベースへ連携するプロジェクトが進行している。\nHIPAA（医療保険の携行性と責任に関する法律）および個人情報保護法に基づき、患者の氏名、住所、電話番号、保険証番号などの直接識別子（PII / PHI）をクラウドAPI（LLM）へ平文で送信することは厳格に禁止されている。\n\n状況・課題:\nカルテ本文には病名と患者の氏名・電話番号が同一の文章内に混在して記述されている。\n\n問い:\n医療プライバシー法規制（HIPAA）を完全に遵守しながら、Claude を用いてカルテから医療データを抽出するためのインライン前処理アーキテクチャはどれか？",
