    "explanation": "【公式アーキテクチャ解説】\n正解は「オンプレミス境界内の前処理でPII検出器を用いて氏名等を仮名化トークンに置換し、抽出後に復元または破棄する設計」です。\n\n機密データ（医療情報PHI、金融情報PII）をLLMで処理する際のゴールドスタンダードが「Client-side De-identification / Tokenization（クライアント側での匿名化・仮名化）」です。\nデータが院内・社内境界を出る前のセキュアなオンプレミス（またはVPC内）で：\n1. Microsoft Presidio等のルールベース＋軽量ローカルNERモデルを用いて氏名、住所、電話番号を検知。\n2. それらを `<PATIENT_ID_001>`, `<PHONE_001>` といった一時的な仮名化トークン（Surrogate Tokens）に置換。\n3. 仮名化されたテキストをClaude APIへ送信して医療データ（病名、投薬情報）を構造化抽出。\n4. 必要に応じて、セキュアな内部環境でのみ元の識別子と再結合（Re-identification）する。\nこれにより、クラウド側には機密個人情報が一切流出せず、HIPAAやGDPRの厳格な要件をクリアできます。\n\n⚠️ 引っかけポイント: HTTPS暗号化は「通信経路の保護」に過ぎず、「クラウドプロバイダへのデータ送信」そのものは保護されないためHIPAA違反になります。",
