    "explanation": "【公式アーキテクチャ解説】\n正解は「各抽出項目にモデルの確信度スコアを付与させ、閾値未満の項目や不整合がある案件のみを人間の専門家にレビュー回付する設計」です。\n\n高リスク業務における「Human-in-the-Loop（HITL）による例外ベースレビュー」の王道設計です。\n抽出スキーマにおいて、各項目ごとに確信度（例: `confidence: 0.0〜1.0`）や根拠テキストを出力させます。\n- **高確信度（例: 0.95以上）かつ論理整合性チェック合格**: 90%以上の案件がストレートパス（Straight-Through Processing / 完全自動化）で即座に承認。\n- **低確信度（例: 0.95未満）または矛盾検知**: 残り10%の境界線上の案件のみを人間の専門オペレーターのレビューキューへ回付。\nこれにより、全体の処理速度を大幅に向上させつつ、ミスが許されない重要項目の品質を100%担保できます。\n\n⚠️ 引っかけポイント: 全件の人間二重入力はAI化の価値を相殺し、高額案件の無審査承認は壊滅的な融資焦げ付きリスクを招きます。",
