    "question": "【シナリオ：金融機関マルチクラウド統合基盤】\n前提: 欧州（EU）および米国（US）の双方に現地法人を持つメガバンクが、グローバル統一のAI基盤を構築している。\nEU一般データ保護規則（GDPR）のデータ主権要件により、「欧州居住者の顧客データは、推論処理およびデータの一時処理を含め、EU管轄区域（アイルランド/フランクフルト等）の境界外へ転送してはならない」という厳格なクロスボーダー移転規制が課されている。\n\n状況・課題:\n単一のグローバル共通APIエンドポイントを使用すると、米国のリージョンで推論処理が実行されてしまい、GDPR違反による巨額の制裁金リスクが発生する。\n\n問い:\nグローバル金融機関におけるデータ主権（Data Sovereignty）とGDPR要件を完全に遵守するためのマルチリージョン・ルーティング設計はどれか？",
