    "question": "【シナリオ：LLM評価・MLOpsパイプライン】\n前提: Claude 3.5 Sonnet の長大なコンテキストウィンドウ（200,000トークン）を活用し、社内の数千件に及ぶ技術ドキュメントや規程PDFを一括投入してナレッジ回答エンジンを運用している。\n\n状況・課題:\n長大コンテキストのさまざまな位置（冒頭、25%、50%の中央部、75%、末尾）に埋め込まれた特定の事実情報を、モデルが正確に検索・想起できる能力（Retrieval Capacity）を定期的にベンチマークテストしたい。\n\n問い:\n長大なコンテキストウィンドウにおける情報想起・検索精度を包括的に評価するための業界標準のストレステスト手法はどれか？",
