      "長大な無関係テキスト群のランダムな位置に特定の秘密情報（針）を埋め込み想起率を測定する「Needle In A Haystack（NIAH）」テスト。",
      "プロンプトの中に砂時計の画像を添付し、20万トークンの処理が終わるまで砂時計が落ち切らないかを検証するテスト。",
      "コンテキスト長が20万トークンに達した時点でサーバーのLANケーブルを物理的に引き抜き、ネットワーク耐性を測るテスト。"
