    "explanation": "【公式エンタープライズ解説】\n正解は「長大な無関係テキスト群のランダムな位置に特定の秘密情報（針）を埋め込み想起率を測定する「Needle In A Haystack（NIAH）」テスト」です。\n\n長文脈LLM（Long-Context Models）の評価における標準ベンチマーク「Needle In A Haystack（干し草の山から針を探す / NIAH）」テストです。\nテストプロトコル：\n1. **干し草（Haystack）**: 数万〜20万トークンの長大なドキュメントテキストを用意。\n2. **針（Needle）**: 「特別なピザのトッピングはイチジクとプロシュートである」といった、干し草と無関係な特定の秘密の事実（針）を1文作成。\n3. **網羅的グリッド検証**: コンテキスト長（10K, 50K, 100K, 200K）× 挿入深度（0%: 冒頭 〜 100%: 末尾）のマトリクスで針を埋め込み、質問に対する正答想起率をヒートマップで可視化。\nClaude 3.5 Sonnet はこのNIAHテストにおいて、200Kコンテキスト全域でほぼ100%の驚異的な想起精度を記録しています。\n\n⚠️ 引っかけポイント: 「あ」の連続やLANケーブルの引き抜きはコンテキスト想起能力の評価にはなりません。",
    "officialRef": "Anthropic Certified Architect Professional: Needle In A Haystack (NIAH) & Long-Context Evaluation"
