    "question": "【シナリオ：LLM評価・MLOpsパイプライン】\n前提: 社内ナレッジを検索して回答を生成するエンタープライズRAG（Retrieval-Augmented Generation）システムを構築した。\n本番運用において、RAGの品質劣化（検索の失敗なのか、生成時のハルシネーションなのか）を診断するための評価メトリクスを設計している。\n\n状況・課題:\n「ユーザーの質問に対して回答が正しくなかった」という事象が発生した際、ベクター検索エンジンの精度不足（適切なドキュメントを取得できなかった）なのか、それともClaudeが取得したドキュメントを無視してハルシネーションを起こしたのかを切り分けられない問題があった。\n\n問い:\nRAGシステムの障害箇所を明確に分離・特定するための「RAG評価の3大主要指標（Ragas等の標準メトリクス）」の組み合わせはどれか？",
