      "ベクターデータベースが稼働する物理サーバーのファン回転数、CPU温度、メモリ使用率の3つのハードウェア健康状態指標のみを常時監視するシステム運用の組み合わせ。",
      "エンドユーザーがチャット会話中に「ありがとう」と言った回数、「役に立たない」と言った回数、「普通」と言った回数の3つの感情単語出現頻度のみを集計する組み合わせ。",
      "取得文脈の妥当性を測る「Context Relevance」、回答が文脈に基づいているかを測る「Faithfulness」、質問に答えているかを測る「Answer Relevance」。"
