    "question": "【シナリオ：LLM評価・MLOpsパイプライン】\n前提: 新しいプロンプトやモデルのリリースにあたり、事前検証としての「オフライン評価（LLM-as-a-Judge）」と、本番での「オンライン評価（A/Bテスト）」の両方を実施している。\n\n状況・課題:\nオフラインのLLMジャッジでは「90点」と高スコアを記録した新プロンプトを本番A/Bテストに投入したところ、実際のユーザーの定着率や満足度（Thumbs-up率）が激減するという「オフライン評価とオンライン指標の乖離」が発生した。\n\n問い:\nオフライン自動評価と本番オンラインユーザー指標の乖離（Misalignment）を解消するための、評価基盤のキャリブレーション設計はどれか？",
