      "本番環境でのA/Bテストの実施を即時中止し、実ユーザーの反応を一切見ずにオフラインテストのスコアだけで100%すべてのリリース判断を下す設計。",
      "本番A/Bテストでのユーザー行動指標（定着率、クリックスルー率）を正解ラベルとし、ジャッジのルーブリック重みを定期キャリブレーションする設計。"
