    "explanation": "【公式エンタープライズ解説】\n正解は「本番A/Bテストでのユーザー行動指標（定着率、クリックスルー率）を正解ラベルとし、ジャッジのルーブリック重みを定期キャリブレーションする設計」です。\n\nLLM評価基盤のメタ評価・整合性（Offline-Online Alignment Calibration）です。\nオフライン評価（LLM-as-a-Judge）はあくまで「人間の好みのシミュレーション」に過ぎません。モデルと実ユーザーの間で価値基準のズレ（例: ジャッジは丁寧な長文を好んだが、現場のユーザーは忙しくて1行の結論を求めていた）が生じることがあります。\nアーキテクチャ設計として：\n本番A/Bテストの実測データ（ユーザー満足度、タスク完了率、コンバージョン率）をグラウンドトゥルースとしてオフライン評価システムへフィードバックし、ジャッジモデルのプロンプトやルーブリックの配点比率（簡潔性の重みを増やす等）を調整（Calibration）し続けることで、オフラインスコアと本番ビジネス成果の一致性を担保します。\n\n⚠️ 引っかけポイント: ユーザー感覚の否定や評価ボタンの隠蔽はプロダクトの死を意味します。",
