    "explanation": "【公式エンタープライズ解説】\n正解は「Anthropic Message Batches APIを活用し、リクエストを一括投入して24時間以内の非同期完了結果を半額のコストで取得する設計」です。\n\nAnthropic Message Batches APIは、リアルタイム性を必要としない大規模バッチ処理専用のエンドポイントです。\n主要な利点：\n1. **コスト50%オフ**: 入力トークンおよび出力トークンのすべての料金が、標準API価格の **一律50%割引** となる。\n2. **別枠のスループット**: オンラインの標準レートリミット（RPM/TPM）とは独立した大容量バッチ処理プールで実行されるため、本番ユーザーのリアルタイムトラフィックを阻害しない。\n3. **24時間以内のSLA**: 最大10,000件（または規定サイズ）のリクエストを1つのバッチとして投入し、多くの場合数時間以内（最大24時間以内）に非同期で結果を取得できる。\n夜間バッチや過去データ分析など、非同期で許容されるワークロードにはMessage Batches APIを採用するのがFinOpsにおける最重要の定石です。\n\n⚠️ 引っかけポイント: 通常同期APIの同時並行送信は429多発と日中トラフィック枯渇を招き、30万件の単一プロンプト連結はコンテキスト制限で失敗します。",
