    "question": "【シナリオ：FinOps・キャパシティ最適化とLLM可観測性】\n前提: シャドウテストによる比較検証をパスしたClaudeの新モデルおよび改訂システムプロンプトを、数百万人のユーザーが利用する本番チャットサービスに正式展開する。\n万が一、実環境の特定ユーザー層でのみ再現する未知の不具合やエラーが発覚した場合、直ちに影響を極小化し、瞬時に旧バージョンへロールバックできる体制が不可欠である。\n\n状況・課題:\n一斉切り替え（ビッグバンリリース）を行うと、障害発生時に全ユーザーが一斉に影響を受け、ブランド価値が失墜する。\nまた、Blue/Greenデプロイメントであっても、切り替えの瞬間に全負荷が新環境に移るため、潜在的バグのリスクを初期段階で隔離できない。\n\n問い:\nリスクを最小限に抑え、実ユーザーのフィードバックとエラーメトリクスを監視しながら安全に本番適用を進めるための、最も優れたデプロイ戦略はどれか？",
