      "偶数分にアクセスした全ユーザーに新版を、奇数分にアクセスした全ユーザーに旧版をランダムに提供し、ログの突合を行わずに放置する設計。",
      "新版のトラフィック比率を社内役員の個人スマートフォン端末のみに限定し、一般ユーザーへの本番リリース判定を役員の主観のみで行う設計。"
