    "explanation": "【公式エンタープライズ解説】\n正解は「API Gatewayの重み付けルーティングで本番トラフィックの1%から新版へ流し、エラー率や満足度KPIを監視しながら段階的に拡大する設計」です。\n\nLLMアプリケーションの無停止・安全リリースにおける最高水準のプラクティスが「カナリアデプロイ（Canary Deployment）」です。\n1. API Gateway / ロードバランサーの重み付けルーティング（Weighted Routing）を使用し、本番トラフィックのごく一部（例: 1%〜5%）のみを新プロンプト/新モデルに流す。\n2. カナリア群とコントロール群（現行版95%）の間で、HTTPエラー率、レイテンシ、ユーザーのGood/Bad評価、会話継続率などのKPIをリアルタイム比較。\n3. 統計的有意性をもって異常がないことを確認した後、10% ➜ 25% ➜ 50% ➜ 100% と段階的にトラフィックをシフト。\n4. 異常メトリクスを検知した場合は、自動アラートと連動してトラフィック比率を即座に0%へ戻す自動ロールバック（Automated Rollback）を実行。\nこれにより、不具合の影響範囲を最小限のユーザーに限定できます。\n\n⚠️ 引っかけポイント: 全面切り替えはリスクが極大であり、時間帯ランダム切り替えは同一ユーザーの会話セッション内でのモデル不整合を引き起こします。",
