    "explanation": "【公式エンタープライズ解説】\n正解は「API応答ヘッダー（`anthropic-ratelimit-*-remaining`等）を監視し、残枠が枯渇する手前で内部トークンバケットにより送信レートを事前抑制する設計」です。\n\nAnthropic Direct APIは、すべてのAPIレスポンスのHTTPヘッダーに現在のレートリミット消費状況をリアルタイムで返却します：\n- `anthropic-ratelimit-requests-limit` / `remaining` / `reset`\n- `anthropic-ratelimit-tokens-limit` / `remaining` / `reset`\nプロアクティブな流量制御を行うアーキテクチャでは、社内APIゲートウェイがこれらのヘッダー値を常に読み取り、残りトークン数（`remaining`）が一定のしきい値（例: 残り15%）を下回った段階で、新規リクエストの送信レートをトークンバケット/リーキーバケットアルゴリズムによって能動的にシェーピング（平滑化）します。\nこれにより、外部APIからHTTP 429が返ってくる事態を完全に先回りして防止できます。\n\n⚠️ 引っかけポイント: 同一APIキーでの分散並行実行は組織クォータに合算されるため回避策にならず、固定ハードコードはクォータ改定時に破綻します。",
