    "question": "【シナリオ：FinOps・キャパシティ最適化とLLM可観測性】\n前提: 大手特許法律事務所において、15万トークンに及ぶ大量の先行特許公報や技術論文を一度にClaudeのコンテキストに入力し、新規出願特許との抵触可能性を精緻に判定させるシステムを運用している。\n検証の結果、コンテキストの最前頭や最後尾に記載された情報は正確に引用・考慮されるものの、コンテキストの中央部（7万〜8万トークン付近）に記載された重要な先行技術の但し書きを見落とし、誤った侵害判定を出力する事象が確認された。\n\n状況・課題:\nこれは大規模言語モデル全般において学術的にも広く知られている「Lost in the Middle（中央情報の見落とし）」現象である。\n特許審査の正確性を担保するため、プロンプトの構成方法によってこの現象を完全に克服する必要がある。\n\n問い:\n超長文コンテキスト処理において、モデルの注意機構（Attention）を最適化し、重要情報の中央埋没を防ぐためのプロンプト構造化の定石はどれか？",
