      "15万トークンの規程テキストをすべてBase64エンコードして1行の文字列に変換し、プロンプトの改行コードをすべて除去して渡す構造。",
      "プロンプト内のコンテキスト情報をすべて逆順（最後の文字から先頭へ）に並べ替え、Claudeに後ろから逆向きに読ませる構造。"
