    "explanation": "【公式エンタープライズ解説】\n正解は「コンテキスト冒頭にタスク指示と文書全体の概要を置き、最重要規程や抽出クエリを末尾にも再配置する「サンドイッチ型」プロンプト構造」です。\n\nLLMのトランスフォーマー構造における自己注意機構（Self-Attention）は、コンテキストの「最初（Primacy Effect）」と「最後（Recency Effect）」に最も強いアテンションが向かい、中央部の情報が相対的に希薄化しやすい「Lost in the Middle」特性を持ちます。\nAnthropic公式のベストプラクティスでは、以下の「サンドイッチ構造」が推奨されます：\n1. **プロンプト冒頭**: ロール定義、タスク指示、入力ドキュメントの構造説明\n2. **プロンプト中間**: 大容量の参照ドキュメント（XMLタグ `<documents>` で囲む）\n3. **プロンプト末尾**: ユーザーからの具体的な質問文、重要な制約条件、回答フォーマット指示（XMLタグ `<instructions>` 等）\n質問や重要制約を末尾に再配置（Recencyを最大化）することで、Claudeは直前に読んだ指示の強い文脈を保持したまま中央のドキュメントを検索・参照できるようになり、精度が劇的に改善します。\n\n⚠️ 引っかけポイント: 中央への情報埋没は悪化を招き、Base64エンコードやテキスト逆順並べ替えはトークン数を無駄に消費しモデルの推論を破壊します。",
