    "question": "【CCAR-F 弱点克服 第1問｜前回正答率: 0%】\nECサイトの注文調査エージェントが、1件の問い合わせに対して「注文詳細の取得(`get_order`)」「配送状況の照会(`get_shipment`)」「決済ステータスの確認(`get_payment`)」という互いに独立した3つのツールを実行する必要があります。現在、エージェントは1ターンにつき1つのツールしか呼び出さず、合計3回のAPIラウンドトリップが発生して応答に9秒かかっています。ラウンドトリップ数を最小化してレイテンシーを削減するための正しいエージェントループおよびメッセージ構成はどれですか。",
