      "1回のassistant応答に含まれる複数のtool_useブロックを並列実行し、全結果を単一のuserメッセージ内のtool_result配列にまとめて1ターンで返却する。",
      "3つのツール定義を1つの巨大なモノリシックJSONスキーマに統合し、バックエンド側の改修を省いたままプロンプトの指示だけで高速化を試みる。",
      "リクエスト時のtool_choiceにdisable_parallel_tool_use: trueを指定し、モデル内部の推論キューを直列化して1回あたりのトークン生成速度を引き上げる。"
