    "explanation": "【解説】\n正解は「「確立された調査結果（合意事実）」と「議論の余地がある主張（対立仮説）」を出力スキーマで明確に分け、各ソースの引用元と不確実性を保持して併記させる。」です。\n\n■ なぜこれが正解か（試験目標の直結コア原則）:\n複数の情報源やサブエージェントから矛盾・対立するデータが集まった際、統合エージェントが勝手に1つの確信的なストーリーに丸めてしまう（Premature consensus / Flattening uncertainty）と、重大な判断ミスを招きます。\n・**確立された調査結果 (Established findings)**: 複数ソースで一貫して確認された事実。\n・**議論の余地がある主張 (Contested claims / Discrepancies)**: ソース間で食い違っている主張や仮説。\nこれらをスキーマレベルで分離し、**どのソース（ファイル、時刻、ワーカー）がどの確度（不確実性）で何を主張しているか（Source-level uncertainty）**をそのまま保持して人間に提示するのが正解の設計です（試験目標の文言そのもの）。",
